'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['runConcurrentInOrder']);
const { runConcurrentInOrder } = api;

assert.throws(() => runConcurrentInOrder(null), TypeError);
assert.throws(() => runConcurrentInOrder({}), TypeError);
assert.throws(() => runConcurrentInOrder([() => 1, 2]), TypeError);

(async () => {
  assert.deepStrictEqual(await runConcurrentInOrder([]), []);

  const tasks = [() => 1, () => Promise.resolve(2), () => 'three'];
  const taskSnapshot = tasks.slice();
  assert.deepStrictEqual(await runConcurrentInOrder(tasks), [1, 2, 'three']);
  assert.deepStrictEqual(tasks, taskSnapshot);

  const releases = [];
  const invoked = [];
  const controlled = [0, 1, 2].map((index) => () => {
    invoked.push(index);
    return new Promise((resolve) => {
      releases[index] = resolve;
    });
  });
  const pending = runConcurrentInOrder(controlled);
  await Promise.resolve();
  assert.deepStrictEqual(invoked, [0, 1, 2]);
  releases[2]('last completed first');
  releases[0]('first completed second');
  releases[1]('middle completed last');
  assert.deepStrictEqual(await pending, [
    'first completed second',
    'middle completed last',
    'last completed first'
  ]);

  const marker = new Error('sync failure');
  await assert.rejects(runConcurrentInOrder([
    () => 'ok',
    () => { throw marker; },
    () => 'still invoked'
  ]), (error) => error === marker);

  const rejection = new Error('async failure');
  await assert.rejects(runConcurrentInOrder([
    () => Promise.resolve('ok'),
    () => Promise.reject(rejection)
  ]), (error) => error === rejection);
})().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

